<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><h1 class="h3 mb-1"><i class="fa fa-chart-simple text-primary me-2"></i><?= htmlspecialchars(t('platform_notifications.statistics')) ?></h1><p class="text-muted mb-0"><?= htmlspecialchars((string) ($notification['assunto'] ?? '')) ?></p></div><a class="btn btn-outline-secondary" href="/platform/notificacoes"><i class="fa fa-arrow-left me-1"></i><?= htmlspecialchars(t('platform_notifications.back')) ?></a></div><div class="row g-3"><div class="col-md-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="text-muted small"><?= htmlspecialchars(t('platform_notifications.seen')) ?></div><strong class="fs-3"><?= (int) ($summary['vistos'] ?? 0) ?></strong></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="text-muted small"><?= htmlspecialchars(t('platform_notifications.confirmed')) ?></div><strong class="fs-3"><?= (int) ($summary['confirmados'] ?? 0) ?></strong></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="text-muted small"><?= htmlspecialchars(t('platform_notifications.email_sent')) ?></div><strong class="fs-3"><?= (int) ($summary['emails_enviados'] ?? 0) ?></strong></div></div></div><div class="col-md-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="text-muted small"><?= htmlspecialchars(t('platform_notifications.email_failed')) ?></div><strong class="fs-3"><?= (int) ($summary['emails_falhos'] ?? 0) ?></strong></div></div></div></div></div>
